# Build beam lines
vertical_beams = {c for r1, c1 in markers for r2, c2 in markers if c1 == c2 and r1 != r2}
horizontal_beams = {r for r1, c1 in markers for r2, c2 in markers if r1 == r2 and c1 != c2}

